// Checkout conversion hook: records paidEvent on successful checkout
const { logPaidEvent } = require('./revenueTracker');

module.exports = function(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function(body) {
    // Detect successful checkout (adjust condition as needed)
    if (req.path === '/api/checkout' && res.statusCode === 200 && body && body.success) {
      const amount = body.amount || 0;
      const currency = body.currency || 'USD';
      logPaidEvent({ amount, currency, timestamp: Date.now() });
    }
    return originalJson(body);
  };
  next();
};
